(5529356, 796743, 89277, '<td valign="top">Ah! How can you waste scotch?!</td>', 'Ah! How can you waste scotch?!', '2009-06-15 13:22:21.000000', NULL, 1),
(5529527, 798035, 107736, '<td valign="top">Wonderfully eye appealing. The colors are are caught up in the swiftness of the the water and the lighting brings beauty to the picture. The title of this certainly fits the image. A 10!!</td>', 'Wonderfully eye appealing. The colors are are caught up in the swiftness of the the water and the lighting brings beauty to the picture. The title of this certainly fits the image. A 10!!', '2009-06-15 14:47:07.000000', NULL, 1),
(5529539, 797437, 107736, '<td valign="top">Somewhat nice and clean. The circular ripples seem to stand still and there are few waves. The angle of the round stones seems to offset the illusion of a complete circle. An 8!</td>', 'Somewhat nice and clean. The circular ripples seem to stand still and there are few waves. The angle of the round stones seems to offset the illusion of a complete circle. An 8!', '2009-06-15 14:49:43.000000', NULL, 1),
(5529542, 796901, 74588, '<td valign="top">courage  9</td>', 'courage  9', '2009-06-15 14:50:20.000000', NULL, 1),
(5529547, 797721, 74588, '<td valign="top">just like it    10</td>', 'just like it    10', '2009-06-15 14:51:38.000000', NULL, 1),
(5529551, 797960, 74588, '<td valign="top">noo not this time  very very boring6</td>', 'noo not this time  very very boring6', '2009-06-15 14:54:00.000000', NULL, 1),
(5529559, 798022, 107736, '<td valign="top">This is lovely. A coolness seems to emanate and just take you in. I love the tonal colors of the greens. It would''ve been more magnificant if the sunlight could have been caught in between all the foliage. A 6!</td>', 'This is lovely. A coolness seems to emanate and just take you in. I love the tonal colors of the greens. It would''ve been more magnificant if the sunlight could have been caught in between all the foliage. A 6!', '2009-06-15 14:57:04.000000', NULL, 1),
(5529561, 797913, 107736, '<td valign="top">This is so clear. The point of ambition is well documented in the photo. A 5.</td>', 'This is so clear. The point of ambition is well documented in the photo. A 5.', '2009-06-15 14:58:19.000000', NULL, 1),
(5529562, 797658, 107736, '<td valign="top">Beautiful but not reality. Over indulgence in the color. A 3.</td>', 'Beautiful but not reality. Over indulgence in the color. A 3.', '2009-06-15 14:59:26.000000', NULL, 1),
(5529567, 798148, 107736, '<td valign="top">This is great! Looks like polished lava rocks. The light and shadow effects give this some life. A 9.</td>', 'This is great! Looks like polished lava rocks. The light and shadow effects give this some life. A 9.', '2009-06-15 15:00:46.000000', NULL, 1),
(5529568, 798168, 107736, '<td valign="top">This is beautiful. The light gives off the sparkle in the droplets which seems to be clinging on the the smooth surfaces of the rocks. A 7.</td>', 'This is beautiful. The light gives off the sparkle in the droplets which seems to be clinging on the the smooth surfaces of the rocks. A 7.', '2009-06-15 15:02:06.000000', NULL, 1),
(5529578, 797966, 107736, '<td valign="top">This is very clean and sharp in its presentation. The colors are vivid and the lighting is great. "On The Rocks" is not what I would have titled this. The stones in the glass take away from the decanter of liquid. A 4.</td>', 'This is very clean and sharp in its presentation. The colors are vivid and the lighting is great. "On The Rocks" is not what I would have titled this. The stones in the glass take away from the decanter of liquid. A 4.', '2009-06-15 15:06:01.000000', NULL, 1),
(5529584, 797025, 107736, '<td valign="top">Rough Edges is correct for this scene. Even the water gives the illusion of having rough edges. The background of blue mountains against the blues of the sky are pretty neat too. A 9.</td>', 'Rough Edges is correct for this scene. Even the water gives the illusion of having rough edges. The background of blue mountains against the blues of the sky are pretty neat too. A 9.', '2009-06-15 15:07:35.000000', NULL, 1),
(5529623, 798050, 106979, '<td valign="top">stack</td>', 'stack', '2009-06-15 15:19:13.000000', NULL, 1);
