(5532253, 797658, 94235, '<td valign="top">Surreal colors. Good low down perspective make this an interesting capture.</td>', 'Surreal colors. Good low down perspective make this an interesting capture.', '2009-06-17 00:51:29.000000', NULL, 1),
(5532259, 797954, 94235, '<td valign="top">Certainly <u>not</u> another boring water shot of rocks in the water! The ripple effect is great although I might have tried a squarer crop to have the ripples completely fill the frame. Great effort all the same.</td>', 'Certainly not another boring water shot of rocks in the water! The ripple effect is great although I might have tried a squarer crop to have the ripples completely fill the frame. Great effort all the same.', '2009-06-17 00:53:50.000000', NULL, 1),
(5532263, 797445, 94235, '<td valign="top">Beautiful color and a surreal setting. Great job!</td>', 'Beautiful color and a surreal setting. Great job!', '2009-06-17 00:54:23.000000', NULL, 1),
(5532266, 798048, 47294, '<td valign="top">This has to be a ''Hugo'' capture if ever I saw one, fantastic landscape, so dramatic!  You have topped my entry, best of luck with the challenge.</td>', 'This has to be a ''Hugo'' capture if ever I saw one, fantastic landscape, so dramatic!  You have topped my entry, best of luck with the challenge.', '2009-06-17 00:54:52.000000', NULL, 1),
